import{_ as e,o as a,c as r,ak as d}from"./chunks/framework.sV-XtlWr.js";const p=JSON.parse('{"title":"Feature map","description":"","frontmatter":{"title":"Feature map","lang":"en-US","editLink":false},"headers":[],"relativePath":"reference/feature-map.md","filePath":"reference/feature-map.md","lastUpdated":null}'),s={name:"reference/feature-map.md"};function o(n,t,i,h,l,u){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="feature-map" tabindex="-1">Feature map <a class="header-anchor" href="#feature-map" aria-label="Permalink to &quot;Feature map&quot;">​</a></h1><p>Everything Piwi does, in one place — what each feature is, what it needs beyond a running <a href="/guide/reporter.html">reporter</a>, where it lives in the dashboard, and the page that explains it. Features are grouped by the three jobs the product serves: <strong>keep the history</strong>, <strong>explain the failures</strong>, and <strong>hand back a fix</strong> — plus how you reach them from elsewhere and what an operator runs.</p><p>New here? Start with <a href="/guide/what-piwi-does.html">What Piwi does</a> and <a href="/guide/getting-started.html">Getting started</a>; this map is the &quot;where next&quot; once a first run has landed.</p><h2 id="keep-the-history" tabindex="-1">Keep the history <a class="header-anchor" href="#keep-the-history" aria-label="Permalink to &quot;Keep the history&quot;">​</a></h2><p>CI deletes every report it makes. Piwi keeps every run, trace and report, so &quot;has this always been flaky?&quot; and &quot;did my fix hold?&quot; are answerable at all.</p><table tabindex="0"><thead><tr><th>Feature</th><th>What it does</th><th>Needs</th><th>Where</th></tr></thead><tbody><tr><td><a href="/features/ui-overview.html">Run history &amp; dashboard map</a></td><td>Every run, trace and HTML report kept and browsable, live-updating as runs start and finish.</td><td>reporter</td><td>Home; Project → Runs</td></tr><tr><td><a href="/features/branches.html">Branches &amp; per-branch baselines</a></td><td>Branch as a first-class dimension: filter by it, and compare against a baseline computed per branch.</td><td>reporter</td><td>Project → filter bar</td></tr><tr><td><a href="/features/run-changes.html">What changed in a run</a></td><td>Compare two runs — newly failing, newly passing, still red — against a chosen baseline.</td><td>reporter</td><td>Test run → Changes</td></tr><tr><td><a href="/guide/importing-runs.html">Import past runs</a></td><td>Backfill history from existing Playwright JSON/blob reports so trends start with a past, not empty.</td><td>admin</td><td>Setup; ingest API</td></tr><tr><td><a href="/features/analytics.html">Analytics &amp; insights</a></td><td>Cross-project trends — portfolio health, wasted CI time, pass-rate heatmap, browser matrix, insights feed.</td><td>reporter</td><td>Analytics</td></tr><tr><td><a href="/features/timeline-markers.html">Timeline markers</a></td><td>Your deploys and infra changes overlaid on the trend charts, so a step change has a cause.</td><td>admin</td><td>Project → Timeline</td></tr><tr><td><a href="/features/notifications.html">Notifications &amp; alerts</a></td><td>Email, Slack, webhook and browser channels with per-project subscriptions, digests and mute.</td><td>reporter</td><td>Settings → Notifications</td></tr><tr><td><a href="/features/offline-export.html">Offline export</a></td><td>A run or execution exported as a self-contained bundle (and a Perfetto trace) that outlives retention.</td><td>reporter</td><td>Run / execution → Export</td></tr><tr><td><a href="/features/share-links.html">Share links</a></td><td>A signed, read-only link to one failure for someone without an account.</td><td>reporter</td><td>Execution → Share</td></tr></tbody></table><h2 id="explain-the-failures" tabindex="-1">Explain the failures <a class="header-anchor" href="#explain-the-failures" aria-label="Permalink to &quot;Explain the failures&quot;">​</a></h2><p>Group forty red tests into the three problems behind them, score the flaky ones by the CI minutes they waste, and — optionally — have an LLM explain a cluster against your real git diff.</p><table tabindex="0"><thead><tr><th>Feature</th><th>What it does</th><th>Needs</th><th>Where</th></tr></thead><tbody><tr><td><a href="/features/evidence.html">Failure evidence</a></td><td>One failing execution, diagnosis-first: error, clues, attempts, trace-powered views and (with fixtures) console, network and ARIA.</td><td>reporter</td><td>Test case → execution</td></tr><tr><td><a href="/features/failure-clusters.html">Failure clusters &amp; the inbox</a></td><td>Failures sharing an error fingerprint collapsed into one cluster, triaged once with an owner and known-issue link.</td><td>reporter</td><td>Test run → Failures; Home</td></tr><tr><td><a href="/features/flaky-tests.html">Flaky tests &amp; quarantine</a></td><td>Flaky detection and cost scoring, with quarantine that keeps a known-bad test running but off the merge gate.</td><td>reporter</td><td>Project → Flaky</td></tr><tr><td><a href="/features/slow-tests.html">Slow tests &amp; wasted time</a></td><td>Slowest tests, timeout headroom, stale <code>test.slow()</code>, slow endpoints and Web Vitals — the time your suite costs.</td><td>capture fixtures</td><td>Project → Performance; Analytics</td></tr><tr><td><a href="/features/ai-diagnosis.html">AI diagnosis</a></td><td>An LLM explains a cluster against your actual diff, with a suggested patch validated against your source first.</td><td>an AI key</td><td>Cluster → Diagnosis</td></tr><tr><td><a href="/guide/backend-logs.html">Backend logs</a></td><td>Server-side warnings, errors and spans captured per test and shown next to the request that triggered them.</td><td>a backend integration</td><td>Execution → network</td></tr></tbody></table><h2 id="hand-back-a-fix" tabindex="-1">Hand back a fix <a class="header-anchor" href="#hand-back-a-fix" aria-label="Permalink to &quot;Hand back a fix&quot;">​</a></h2><p>The point is to leave with something to do, not just something to read: a ranked replacement locator, a validated patch, an owner, and the command that verifies the work.</p><table tabindex="0"><thead><tr><th>Feature</th><th>What it does</th><th>Needs</th><th>Where</th></tr></thead><tbody><tr><td><a href="/features/locator-healing.html">Locator healing</a></td><td>When a selector breaks, ranked replacement locators captured from the last passing run, with a recommended fix.</td><td>capture fixtures</td><td>Execution → Locator fix</td></tr><tr><td><a href="/features/fix-plans.html">Fix plans, reproduce &amp; bisect</a></td><td>A plan to reproduce a failure locally and bisect to the commit that introduced it.</td><td>the desktop app</td><td>Cluster / execution → Fix plan</td></tr><tr><td><a href="/features/auto-heal.html">Auto-heal PRs</a></td><td>A pull request opened for you with a validated locator or patch — you review and merge, Piwi never does.</td><td>an SCM token, an AI key</td><td>Settings → AI diagnosis</td></tr><tr><td><a href="/guide/ci.html">Pull-request feedback &amp; re-run</a></td><td>A summary of the failures on the branch posted to the PR, and a re-run triggered from the dashboard.</td><td>an SCM token</td><td>Settings → Pull requests</td></tr><tr><td><a href="/reference/cli.html">CI merge gate</a></td><td>A <code>piwi gate</code> command that blocks a merge on new failures or flakiness, with the run URL in the CI log.</td><td>reporter</td><td>CI (<code>piwi gate</code>)</td></tr><tr><td><a href="/guide/test-selection.html">Test selections &amp; impact</a></td><td>Run only the tests that matter — changed files, a subset, balanced shards — from the CLI or the dashboard.</td><td>reporter</td><td>Project → Selections; CLI</td></tr><tr><td><a href="/guide/ai-steps.html">AI steps</a></td><td>Author and replay natural-language test steps an LLM turns into Playwright actions.</td><td>an AI key</td><td>Reporter config</td></tr></tbody></table><h2 id="use-it-from-elsewhere" tabindex="-1">Use it from elsewhere <a class="header-anchor" href="#use-it-from-elsewhere" aria-label="Permalink to &quot;Use it from elsewhere&quot;">​</a></h2><p>Reach your results and act on them from wherever you already work.</p><table tabindex="0"><thead><tr><th>Feature</th><th>What it does</th><th>Needs</th><th>Where</th></tr></thead><tbody><tr><td><a href="/features/mcp.html">MCP server</a></td><td>A Model Context Protocol server that gives coding agents read access to your runs, failures and diagnoses.</td><td>reporter</td><td>MCP server (<code>/mcp</code>)</td></tr><tr><td><a href="/features/mcp.html#agent-skills">Agent skills</a></td><td>Installable skills that teach a coding agent the Piwi failure-fixing workflow end to end.</td><td>reporter</td><td>reporter CLI (<code>piwi skills</code>)</td></tr><tr><td><a href="/features/desktop.html">Desktop app</a></td><td>A local instance in a desktop shell — run tests, reproduce and bisect, with one-click MCP wiring.</td><td>the desktop app</td><td>Desktop app</td></tr><tr><td><a href="/features/extension.html">Browser extension</a></td><td>Record actions, build and lint locators, and copy context for an agent, straight from the page.</td><td>the browser extension</td><td>Browser extension</td></tr><tr><td><a href="/features/test-functions.html">Test functions catalog</a></td><td>The reusable helpers and page-object methods your suite calls, catalogued with their parameters.</td><td>reporter</td><td>Project → Test functions</td></tr><tr><td><a href="/features/ide-integration.html">Open in IDE</a></td><td>Every source path in the dashboard jumps to that file and line in VS Code or JetBrains.</td><td>reporter</td><td>any source path</td></tr></tbody></table><h2 id="run-your-instance" tabindex="-1">Run your instance <a class="header-anchor" href="#run-your-instance" aria-label="Permalink to &quot;Run your instance&quot;">​</a></h2><p>Operate a shared, self-hosted instance for a team.</p><table tabindex="0"><thead><tr><th>Feature</th><th>What it does</th><th>Needs</th><th>Where</th></tr></thead><tbody><tr><td><a href="/operate/authentication.html">Authentication &amp; roles</a></td><td>Optional sign-in with roles (admin, reporter, viewer), API keys for CI, and Google/GitHub OAuth.</td><td>admin</td><td>Settings → Users</td></tr><tr><td><a href="/operate/authentication.html#project-access">Project access</a></td><td>Scope who can see and act on each project, for multi-team instances.</td><td>admin</td><td>Settings → Users</td></tr><tr><td><a href="/operate/storage.html#data-retention">Data retention &amp; cleanup</a></td><td>Cap how much run history you keep, with a nightly sweep and manual bulk cleanup.</td><td>admin</td><td>Settings → Storage</td></tr><tr><td><a href="/operate/backup-restore.html">Backup &amp; restore</a></td><td>What to copy for a safe backup of the database and file storage, and how to restore it.</td><td>admin</td><td>operator (filesystem)</td></tr></tbody></table>',18)])])}const f=e(s,[["render",o]]);export{p as __pageData,f as default};
